#include "stxlib/types.hpp"

namespace stxlib::detail::ic::memory {

// memory::allocate: power_of_two(alignment); else returns null.
[[nodiscard]] constexpr bool admits_allocate(const usize alignment) noexcept {
    const bool result = alignment != 0 && (alignment & (alignment - 1)) == 0;
    return result;
}

} // namespace stxlib::detail::ic::memory
